//! Rail modes, their design values and the switches and crossings catalogue.
//!
//! Defaults come from the assumption library (ADR-0018): `data/defaults.json` is generated by
//! `tools/assumptions/check.py --render` from `assumptions/`, so every number has a source or a
//! documented derivation there. A project can override any value (Project Preferences).

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::sync::OnceLock;

/// Rail modes drawn with the railway design tool (ADR-0030).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RailMode {
    /// Street tram.
    Tram,
    /// Light rail / Stadtbahn.
    LightRail,
    /// Metro / underground.
    Metro,
    /// Commuter rail / S-Bahn.
    CommuterRail,
    /// Regional rail.
    RegionalRail,
    /// Intercity / long-distance rail.
    LongDistanceRail,
    /// High-speed rail.
    HighSpeedRail,
}

impl RailMode {
    /// All rail modes in display order.
    pub const ALL: [RailMode; 7] = [
        RailMode::Tram,
        RailMode::LightRail,
        RailMode::Metro,
        RailMode::CommuterRail,
        RailMode::RegionalRail,
        RailMode::LongDistanceRail,
        RailMode::HighSpeedRail,
    ];

    /// Purpose: the mode id used in the assumption library.
    pub fn id(self) -> &'static str {
        match self {
            RailMode::Tram => "tram",
            RailMode::LightRail => "light_rail",
            RailMode::Metro => "metro",
            RailMode::CommuterRail => "commuter_rail",
            RailMode::RegionalRail => "regional_rail",
            RailMode::LongDistanceRail => "long_distance_rail",
            RailMode::HighSpeedRail => "high_speed_rail",
        }
    }

    /// Purpose: whether the mode usually runs in streets (embedded track, no cant there).
    pub fn street_running(self) -> bool {
        matches!(self, RailMode::Tram | RailMode::LightRail)
    }
}

/// Design values of one rail mode. Field meanings and sources: `assumptions/DEFAULTS.md`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ModeParams {
    /// Display name.
    pub label: String,
    /// Track gauge, mm.
    pub gauge_mm: f64,
    /// Design (line) speed, km/h.
    pub design_speed_kmh: f64,
    /// Track centre distance on double track, m.
    pub track_centre_m: f64,
    /// Distance between track centres at the clearance marker (fouling point), m.
    pub clearance_marker_m: f64,
    /// Minimum horizontal radius, m (error below).
    pub min_radius_m: f64,
    /// Recommended radius, m (default for new curves; warning below).
    pub recommended_radius_m: f64,
    /// Maximum gradient, ‰.
    pub max_gradient_permille: f64,
    /// Minimum vertical curve radius, m.
    pub vertical_radius_m: f64,
    /// Transition design: maximum rate of change of cant, mm/s.
    pub cant_change_rate_mm_s: f64,
    /// Transition design: maximum rate of change of cant deficiency, mm/s.
    pub cant_deficiency_change_rate_mm_s: f64,
    /// Transition design: maximum cant gradient, mm/m.
    pub max_cant_gradient_mm_m: f64,
    /// Maximum applied cant, mm.
    pub max_cant_mm: f64,
    /// Maximum cant deficiency, mm.
    pub max_cant_deficiency_mm: f64,
    /// Default platform length, m.
    pub platform_length_m: f64,
    /// Platform height above rail, mm.
    pub platform_height_mm: f64,
    /// Side platform width, m.
    pub side_platform_width_m: f64,
    /// Island platform width, m.
    pub island_platform_width_m: f64,
    /// Track centre to platform edge, m.
    pub platform_edge_offset_m: f64,
    /// Station track beyond each platform end, m.
    pub track_beyond_platform_m: f64,
    /// Depth per underground level, m.
    pub underground_level_depth_m: f64,
    /// Height per elevated level, m.
    pub elevated_level_height_m: f64,
    /// Structure outline beyond the rails on each side (drawing), m.
    pub structure_outline_m: f64,
    /// Default energy supply system id (`assumptions/supply-systems.yaml`), or `none`.
    pub electrification: String,
    /// Overhead line span (mast spacing), m.
    pub ocl_span_m: f64,
    /// Default turnout id from the catalogue.
    pub default_turnout: String,
    /// Train acceleration, m/s².
    pub acceleration_ms2: f64,
    /// Service braking, m/s².
    pub service_braking_ms2: f64,
    /// Line colour.
    pub colour: String,
    /// Street lane width, m (carriageway width where OSM has no `width`).
    pub street_lane_width_m: f64,
    /// Lanes of a two-way street where OSM has no `lanes`.
    pub street_lanes: f64,
    /// Speed limit of a street without an OSM `maxspeed`, km/h.
    pub street_speed_limit_kmh: f64,
    /// Walking pace in a living street or pedestrian zone, km/h.
    pub street_walking_pace_kmh: f64,
    /// Extra running time in the traffic of a main road, share of the free-flow time.
    pub street_mixed_traffic_delay_share: f64,
    /// Extra running time in a painted (not separated) tram or bus lane, share.
    pub street_bus_lane_delay_share: f64,
    /// Road vehicles stop this far outside a crossing's conflict area, m.
    pub road_stop_clearance_m: f64,
    /// Whether the mode may cross streets on the level (`yes` or `no`).
    pub level_crossing_permitted: String,
    /// Highest line speed over a level crossing, km/h.
    pub level_crossing_max_speed_kmh: f64,
    /// Smallest angle between track and street at a level crossing, degrees.
    pub level_crossing_min_angle_deg: f64,
    /// Warning time before a train reaches a level crossing, s.
    pub level_crossing_warning_time_s: f64,
    /// Time from the train clearing a level crossing until road traffic may go again, s.
    pub level_crossing_reopen_s: f64,
    /// Longest peak headway of a line, min (`timetable.policy_headway_peak_min`): the
    /// assumed service at level crossings until a timetable exists.
    pub policy_headway_peak_min: f64,
    /// Longest off-peak headway of a line, min (`timetable.policy_headway_offpeak_min`).
    pub policy_headway_offpeak_min: f64,
    /// Train control: `line_of_sight`, `fixed_block`, `cbtc` or `etcs_l2`.
    pub signalling_system: String,
    /// Distance of a signal in front of the switch point it protects, m.
    pub signal_before_switch_m: f64,
    /// Overlap for approach speeds up to 40 km/h, m.
    pub overlap_31_40_m: f64,
    /// Overlap for approach speeds of 41–60 km/h, m.
    pub overlap_41_60_m: f64,
    /// Overlap above 60 km/h, m.
    pub overlap_above_60_m: f64,
    /// Sighting distance added to the braking distance for lineside signals, m.
    pub sighting_m: f64,
}

impl ModeParams {
    /// Purpose: gauge in metres.
    pub fn gauge_m(&self) -> f64 {
        self.gauge_mm / 1000.0
    }
    /// Purpose: maximum gradient as a ratio (m per m).
    pub fn max_gradient(&self) -> f64 {
        self.max_gradient_permille / 1000.0
    }
    /// Purpose: whether the default supply is a third (or fourth) rail.
    pub fn third_rail_default(&self) -> bool {
        self.electrification.starts_with("third-rail")
            || self.electrification.starts_with("fourth-rail")
    }
}

/// Kind of a catalogue element.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Element {
    /// Simple turnout.
    Turnout,
    /// Crossover between two parallel tracks (two turnouts).
    Crossover,
    /// Scissors crossover (two crossovers and a diamond).
    ScissorsCrossover,
    /// Diamond crossing.
    Diamond,
    /// Single slip.
    SingleSlip,
    /// Double slip.
    DoubleSlip,
}

/// One element of the switches and crossings catalogue (`assumptions/switches.yaml`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SwitchSpec {
    /// Catalogue id.
    pub id: String,
    /// Display name.
    pub label: String,
    /// Kind.
    pub element: Element,
    /// Diverging curve shape (`curved-crossing`, `straight-crossing`, `transition`).
    #[serde(default)]
    pub geometry: Option<String>,
    /// For crossovers: the turnout they are built from.
    #[serde(default)]
    pub built_from: Option<String>,
    /// Modes it is typically used on.
    #[serde(default)]
    pub typical_modes: Vec<RailMode>,
    /// Crossing ratio 1:n.
    #[serde(default)]
    pub crossing_ratio_n: Option<f64>,
    /// Crossing angle (diamonds without a ratio), degrees.
    #[serde(default)]
    pub crossing_angle_deg: Option<f64>,
    /// Smallest radius of the diverging track, m.
    #[serde(default)]
    pub radius_m: Option<f64>,
    /// Start of switch to intersection point, m.
    #[serde(default)]
    pub length_a_m: Option<f64>,
    /// Intersection point to the end of each leg, m.
    #[serde(default)]
    pub length_b_m: Option<f64>,
    /// Total length, m.
    #[serde(default)]
    pub total_length_m: Option<f64>,
    /// Permitted speed on the diverging track, km/h.
    #[serde(default)]
    pub diverging_speed_kmh: Option<f64>,
    /// Permitted speed on the through track, km/h.
    #[serde(default)]
    pub through_speed_kmh: Option<f64>,
    /// Crossovers: track centre distance of the catalogue entry, m.
    #[serde(default)]
    pub track_centre_m: Option<f64>,
}

/// Turnout geometry needed for drawing: angle, radius and the a/b lengths.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct TurnoutGeometry {
    /// Crossing angle, rad.
    pub alpha: f64,
    /// Diverging radius used for drawing, m.
    pub radius: f64,
    /// Straight run from the switch start before the curve, m.
    pub lead: f64,
    /// Start to intersection point, m.
    pub a: f64,
    /// Intersection point to each leg end, m.
    pub b: f64,
    /// Diverging speed, km/h.
    pub diverging_kmh: f64,
    /// Crossing ratio n.
    pub n: f64,
}

impl SwitchSpec {
    /// Purpose: drawing geometry of a turnout (None for other elements or missing values).
    /// The diverging centre line runs straight for `a − R·tan(α/2)`, then on radius R through α,
    /// then straight, so it passes through the intersection point at `a` and its leg is `b` long.
    pub fn turnout_geometry(&self) -> Option<TurnoutGeometry> {
        if self.element != Element::Turnout {
            return None;
        }
        let n = self.crossing_ratio_n?;
        let alpha = (1.0 / n).atan();
        let a = self.length_a_m?;
        let mut radius = self.radius_m?;
        let tangent = radius * (alpha / 2.0).tan();
        if tangent > a {
            radius = a / (alpha / 2.0).tan();
        }
        Some(TurnoutGeometry {
            alpha,
            radius,
            lead: (a - radius * (alpha / 2.0).tan()).max(0.0),
            a,
            b: self.length_b_m?,
            diverging_kmh: self.diverging_speed_kmh.unwrap_or(0.0),
            n,
        })
    }
}

/// An energy supply system (`assumptions/supply-systems.yaml`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SupplySystem {
    /// Display name.
    pub label: String,
    /// `ocl`, `trolley`, `third-rail` or `fourth-rail`.
    pub collection: String,
    /// `ac` or `dc`.
    pub current: String,
}

/// The generated defaults file.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Defaults {
    /// Design values per rail mode.
    pub modes: BTreeMap<RailMode, ModeParams>,
    /// Supply systems by id.
    pub supply_systems: BTreeMap<String, SupplySystem>,
    /// Switches and crossings catalogue.
    pub switches: Vec<SwitchSpec>,
}

/// Purpose: the defaults generated from the assumption library (parsed once).
pub fn defaults() -> &'static Defaults {
    static D: OnceLock<Defaults> = OnceLock::new();
    D.get_or_init(|| {
        serde_json::from_str(include_str!("../data/defaults.json"))
            .expect("data/defaults.json is generated by tools/assumptions/check.py and valid")
    })
}

impl Defaults {
    /// Purpose: design values of a mode.
    pub fn mode(&self, m: RailMode) -> &ModeParams {
        &self.modes[&m]
    }
    /// Purpose: catalogue element by id.
    pub fn switch(&self, id: &str) -> Option<&SwitchSpec> {
        self.switches.iter().find(|s| s.id == id)
    }
    /// Purpose: turnouts usable for a mode, smallest radius first.
    pub fn turnouts_for(&self, m: RailMode) -> Vec<&SwitchSpec> {
        let mut v: Vec<&SwitchSpec> = self
            .switches
            .iter()
            .filter(|s| s.element == Element::Turnout && s.typical_modes.contains(&m))
            .collect();
        v.sort_by(|a, b| {
            a.radius_m
                .unwrap_or(0.0)
                .total_cmp(&b.radius_m.unwrap_or(0.0))
        });
        v
    }
    /// Purpose: flattest diamond crossing in the catalogue, as ratio n of 1:n.
    pub fn flattest_diamond_n(&self) -> f64 {
        self.switches
            .iter()
            .filter(|s| s.element == Element::Diamond)
            .filter_map(|s| s.crossing_ratio_n)
            .fold(1.0, f64::max)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn defaults_cover_every_mode_and_default_turnout() {
        let d = defaults();
        for m in RailMode::ALL {
            let p = d.mode(m);
            assert!(p.min_radius_m <= p.recommended_radius_m, "{m:?}");
            let t = d
                .switch(&p.default_turnout)
                .expect("default turnout in catalogue");
            assert!(t.turnout_geometry().is_some(), "{}", t.id);
        }
        assert!(d.flattest_diamond_n() >= 9.0);
    }

    #[test]
    fn turnout_geometry_matches_catalogue_crossover_length() {
        // Crossover length = 2a + e·n (assumptions/README.md); check DB EW 190-1:9 at 4.5 m.
        let t = defaults()
            .switch("db-ew-190-1-9")
            .unwrap()
            .turnout_geometry()
            .unwrap();
        let x = 2.0 * t.a + 4.5 * t.n;
        assert!((x - 64.944).abs() < 0.01, "{x}");
    }
}
